def shortest_paths(source, weight_by_edge):
    # Initialize the distance dictionary with infinity for all nodes except the source node
    distance = {node: float('inf') for node in set(weight_by_edge)}
    distance[source] = 0

    # Perform V-1 iterations where V is the number of nodes in the graph
    for _ in range(len(distance) - 1):
        for u, v, weight in weight_by_edge.items():
            # Update the distance if a shorter path through the current node exists
            if distance[u] != float('inf') and distance[u] + weight < distance[v]:
                distance[v] = distance[u] + weight

    # Check for negative-weight cycles using the Bellman-Ford algorithm
    for u, v, weight in weight_by_edge.items():
        if distance[u] != float('inf') and distance[u] + weight < distance[v]:
            raise ValueError("The graph contains a negative-weight cycle")

    return distance
